def pid(n,k): return f'stat11-s{n:03}-{k}'
def curve(aria,path,W=420,H=220,avg=None,title=None,avg_label=False):
    o=f'<line x1="40" y1="15" x2="40" y2="{H-45}" stroke="#222" stroke-width="1.5"/><line x1="40" y1="{H-45}" x2="{W-45}" y2="{H-45}" stroke="#222" stroke-width="1.5"/>'
    o+=T(46,12,'y-axis',12,'start')+T(W-8,H-40,'x-axis',12,'end')+T(30,H-38,'0',12,'end')
    o+=f'<path d="{path}" fill="none" stroke="#1c6aa8" stroke-width="2.2"/>'
    if avg is not None:
        x,ytop=avg
        o+=f'<line x1="{x}" y1="{ytop}" x2="{x}" y2="{H-45}" stroke="#1c6aa8" stroke-width="2"/>'+T(x,H-24,'Average',12)
    if title:o+=T(W/2+60,30,title,12,'middle')
    return svg(W,H,aria,o)
